156	class DittoReader:
157	    """The user interface reads platform twins, never the simulator's memory.
158	
159	    A single Ditto bulk GET supplies all twins. Cache is updated independently
160	    so HTTP clients do not multiply platform requests or block the model.
161	    """
162	    def __init__(self, url, password):
163	        twins = json.loads(Path(__file__).with_name("twins.json").read_text(encoding="utf-8"))
164	        self.expected = {thing_id.split(":", 1)[1] for thing_id in twins}
165	        self.url = url.rstrip("/") + "/api/2/things?" + urlencode({"ids": ",".join(twins)})
166	        self.auth = "Basic " + base64.b64encode(f"ditto:{password}".encode()).decode()
167	        self.lock = threading.Lock()
168	        self.state = None
169	        self.last_change = 0.
170	        self.history = deque(maxlen=900)
171	
172	    def refresh(self):
173	        request = Request(self.url, headers={"Authorization": self.auth})
174	        with urlopen(request, timeout=15) as response:
175	            things = json.load(response)
176	        twins = {item["thingId"].split(":", 1)[1]: item["features"] for item in things}
177	        if not self.expected.issubset(twins):
178	            raise ValueError("incomplete platform snapshot")
179	        values = {name: f["properties"]["value"] for name, f in twins["Mass_Balance"].items()}
180	        revision = values.pop("revision")
181	        virtual_time = values.pop("simulation_time")
182	        with self.lock:
183	            if not self.state or self.state["revision"] != revision:
184	                self.last_change = time.monotonic()
185	                self.history.append({"time": virtual_time, **values})
186	            self.state = {"source": "Eclipse Ditto", "timestamp": time.time(), "virtual_time": virtual_time,
187	                          "revision": revision, "fraud": bool(values.get("fraud_active", values["fraud_offset"] != 0)),
188	                          "fraud_direction": values.get("fraud_direction", -1 if values["fraud_offset"] < 0 else 1),
189	                          "fraud_mode": values.get("fraud_mode", os.getenv("FRAUD_MODE", "fixed")), "audit": values,
190	                          "twins": twins}
191	
192	    def snapshot(self):
193	        with self.lock:
194	            if self.state is None:
195	                raise RuntimeError("waiting for platform telemetry in Ditto")
